import{_ as e}from"./index-BpWegA5b.js";import{e as t,c as i,x as s,a as o,g as a,j as l,h as n,i as r}from"./vendor-BS_IPA7n.js";import"./gsap-BkncV2S3.js";const c={class:"min-h-screen pt-32 pb-20 px-6 max-w-4xl mx-auto text-white"},d={class:"mt-12 text-center"},u=e({},[["render",function(e,u){const m=r("router-link");return t(),i("div",c,[u[1]||(u[1]=s('<h1 class="text-4xl font-bold mb-8">Complaints Policy</h1><div class="space-y-8 text-neutral-300 leading-relaxed"><section><h2 class="text-2xl font-bold text-white mb-4">1. Our Commitment</h2><p>We are committed to providing high-quality services. If you are dissatisfied with any aspect of our service, we want to hear from you so we can address your concerns fairly and promptly.</p></section><section><h2 class="text-2xl font-bold text-white mb-4">2. Time Limits</h2><div class="p-4 bg-amber-500/10 border border-amber-500/30 rounded-xl"><p class="text-amber-400 font-medium">Complaints must be submitted within 14 days of the issue occurring. Complaints received after this period may not be considered unless exceptional circumstances apply.</p></div></section><section><h2 class="text-2xl font-bold text-white mb-4">3. How to Complain</h2><p>Please submit your complaint in writing to:</p><div class="mt-4 p-4 bg-neutral-800 rounded-xl"><p class="font-medium text-white">Jake Fieldhouse Consulting Ltd</p><p>Email: <a href="mailto:jake@jakefieldhouse.co.uk" class="text-blue-400 hover:underline">jake@jakefieldhouse.co.uk</a></p><p class="text-sm text-neutral-500 mt-2">Subject line: &quot;Formal Complaint – [Your Name]&quot;</p></div><p class="mt-4">Please include:</p><ul class="list-disc list-inside space-y-2 mt-2"><li>Your name and contact details</li><li>Date of the incident or issue</li><li>Description of the problem</li><li>What outcome you are seeking</li></ul></section><section><h2 class="text-2xl font-bold text-white mb-4">4. Our Process</h2><div class="space-y-4"><div class="flex gap-4"><div class="flex-shrink-0 w-8 h-8 bg-blue-500/20 rounded-full flex items-center justify-center text-blue-400 font-bold">1</div><div><p class="font-medium text-white">Acknowledgement</p><p class="text-sm">We will acknowledge your complaint within 3 business days.</p></div></div><div class="flex gap-4"><div class="flex-shrink-0 w-8 h-8 bg-blue-500/20 rounded-full flex items-center justify-center text-blue-400 font-bold">2</div><div><p class="font-medium text-white">Investigation</p><p class="text-sm">We will investigate the matter and may contact you for additional information.</p></div></div><div class="flex gap-4"><div class="flex-shrink-0 w-8 h-8 bg-blue-500/20 rounded-full flex items-center justify-center text-blue-400 font-bold">3</div><div><p class="font-medium text-white">Response</p><p class="text-sm">We aim to provide a full response within 14 business days. Complex cases may take longer.</p></div></div></div></section><section><h2 class="text-2xl font-bold text-white mb-4">5. Possible Outcomes</h2><p>Depending on our findings, we may:</p><ul class="list-disc list-inside space-y-2 mt-4"><li>Apologise and explain what happened</li><li>Take corrective action to prevent recurrence</li><li>Offer a remedy we consider reasonable (at our discretion)</li><li>Explain why no further action will be taken</li></ul><p class="mt-4 text-sm text-neutral-500">We reserve the right to determine what remedy, if any, is appropriate. This policy does not create any right to compensation.</p></section><section><h2 class="text-2xl font-bold text-white mb-4">6. If You Remain Dissatisfied</h2><p>If you are not satisfied with our response, you may consider:</p><ul class="list-disc list-inside space-y-2 mt-4"><li><strong class="text-white">Alternative Dispute Resolution (ADR):</strong> You may be able to use an ADR scheme, though we are not currently registered with one.</li><li><strong class="text-white">Trading Standards:</strong> Contact your local Trading Standards office via Citizens Advice (0808 223 1133).</li><li><strong class="text-white">Legal Action:</strong> You may have the right to pursue the matter through the courts, subject to applicable limitation periods.</li></ul></section><section><h2 class="text-2xl font-bold text-white mb-4">7. Vexatious Complaints</h2><p>We reserve the right to decline to engage further with complaints that are, in our reasonable opinion, vexatious, repetitive without new information, or made in bad faith.</p></section><p class="text-neutral-500 text-sm pt-8">Last updated: February 2026</p></div>',2)),o("div",d,[a(m,{to:"/",class:"text-neutral-500 hover:text-white transition-colors"},{default:l(()=>[...u[0]||(u[0]=[n("← Back to Home",-1)])]),_:1})])])}]]);export{u as default};
